<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$id=(int)($_GET['id']??0);$u=current_user();$sql="SELECT r.*,e.title,e.event_date,u.name FROM event_registrations r JOIN events e ON e.id=r.event_id JOIN users u ON u.id=r.user_id WHERE r.id=? AND r.attendance_status='attended'";$args=[$id];if($u['role']!=='admin'){$sql.=" AND r.user_id=?";$args[]=$u['id'];}$s=$pdo->prepare($sql);$s->execute($args);$r=$s->fetch();if(!$r){http_response_code(403);exit('Certificate is not available. Attendance must be confirmed.');}app_header('Certificate');?>
<div class="certificate"><div class="cert-inner"><span class="eyebrow">CERTIFICATE OF PARTICIPATION</span><h1>Certificate</h1><p>This is proudly presented to</p><h2><?=e($r['name'])?></h2><p>for participating in</p><h3><?=e($r['title'])?></h3><p>held on <?=e($r['event_date'])?> at our college.</p><div class="cert-footer"><span>College Event Committee</span><span>Registration #<?= (int)$r['id']?></span></div></div></div><div class="center no-print"><button class="btn" onclick="window.print()">Print / Save as PDF</button></div><?php app_footer();?>
